def min_operations_to_rearrange(n, s, t):
    # Initialize dictionary to count differences and table to store minimized distances
    diff_count = {b: s.count(b) for b in {'B', 'W'}}
    memo = [[-1] * (n + 2) for _ in range(n + 2)]

    # Base case: if strings s and t are the same, no operations are needed
    if s == t:
        return 0
    elif memo[n + 1][n + 2] != -1:
        return memo[n + 1][n + 2]

    # Calculate minimum number of operations to bring adjacent stones into the correct order
    for i in range(n - 1, -1, -1):
        for j in range(i + 2, n + 2):
            # Calculate the new order of stones after one operation
            temp_s = s[:i] + s[j] + s[i:j] + s[j+1:]
            temp_t = t[:i] + t[j] + t[i:j] + t[j+1:]
            # If the new strings differ by only one swap, add the cost of one operation and memoize the result
            if diff_count[temp_s[i + 1]] == diff_count[temp_t[i + 1]] and diff_count[temp_s[j]] == diff_count[temp_t[j]] and memo[i + 1][j] == -1:
                memo[i + 1][j] = 1 + memo[i + 2][j + 1]

    # Calculate the minimum number of operations to reach the target configuration
    return 1 + memo[1][n]
