def count_bob_winning_sequences(s: str) -> int:
    MOD = 10 ** 9 + 7
    opponents = {'F': 'W', 'W': 'E', 'E': 'F'}
    mapping = {} # store count of distinct sequences with same ending

    def recurse(i, tail):
        if i == len(s)-1:
            return 1 if tail == '' else 0
        total = 0
        for k in mapping.keys():
            if s[i] == opponents[k[-1]] and not k.endswith(tail):
                total = (total + (mapping[k] * recurse(i+1, tail + k))) % MOD
        mapping[s[i] + tail] = mapping.get(s[i] + tail, 0) + 1
        Bobs_choices = opponents[s[i]] + tail
        for j in range(i+1, len(s)):
            if s[j] != Bobs_choices[-1] and s[j] not in Bobs_choices:
                total = (total + recurse(j, Bobs_choices)) % MOD
        return total % MOD
    return recurse(0, '')
