def min_swaps_to_group_ones(n: int, s: str) -> int:
    ones_count = s.count('1')
    if ones_count == n or ones_count == 0:
        return 0
    left = [0] * n
    right = [0] * n
    swaps = 0
    for i in range(1, n):
        if s[i] == '1' and s[i - 1] == '0':
            left[i] = left[i - 1] + 1
        elif s[i] == '0' and s[i - 1] == '1':
            right[i] = right[i - 1] + 1
            swaps += left[i - 1]
    for i in range(n - 1, 0, -1):
        if s[i] == '1' and right[i] > 0:
            swaps += right[i]
            right[i] = 0
