import itertools
mod = 998244353

def count_strongly_connected_partitions(n: int, s: str)-> int:
    # Create a graph
    graph = defaultdict(list)
    for i in range(1, 2 * n + 1):
        if i != 2 * (i - 1) + 1:
            graph[i].append(2 * i - 1)
            graph[2 * i - 1].append(i)

    # Color the graph using a backtracking approach
    def color(node, color, used, graph):
        used[node] = color
        for connected_node in graph[node]:
            if connected_node not in used:
                if color == 'W' and connected_node in used and used[connected_node] == 'B':
                    return None
                if color_cycle(connected_node, color, used, graph):
                    return None
        if len(graph) == len(used):
            return 1
        for c in ['W', 'B']:
            if not color(connected_node, c, used.copy(), graph):
                return None
        return 0

    def color_cycle(node, color, used, graph):
        visited = set()
        stack = [node]
        while stack:
            curr_node = stack.pop()
            if curr_node in visited or curr_node in used:
                continue
            visited.add(curr_node)
            if curr_node in used and used[curr_node] != color:
                return True
            for connected_node in graph[curr_node]:
                if connected_node in visited or connected_node in used:
                    continue
                stack.append(connected_node)
        return False

    # Initialize used
    used = [None] * (2 * n + 1)

    # Backtrack to find possible colorings
    return sum(list(map(color, range(1, 2 * n + 1), itertools.cycle(['W', 'B']), used))) % mod
