def kth_alternating_permutation(n, k):
    perms = list(permutations(range(1, n+1), n))
    even = []
    odd = []
    for perm in perms:
        if sum(perm[i] % 2 for i in range(len(perm)) // 2) == 0:
            even.append(perm)
        else:
            odd.append(perm)
    if len(even) + 1 < k:
