def can_tile_grid(n, h, w, tiles):
    # Create a recursive function to try placing tiles in the grid
    def place_tiles(x, y, tile, used, grid, remaining_tiles):
        # Base case: if reached the bottom of the grid
        if y + tile[1] > h:
            if not remaining_tiles:
                return True
            return False
        # Check if current cell is already used
        if (x, y) in used or (x, y + tile[1]) in used or (x + tile[0], y) in used or (x + tile[0], y + tile[1]) in used:
            return False
        # Try to place the current tile
        if (x + tile[0] <= w) and place_tiles(x + tile[0], y + tile[1], tile, used + ((x, y),), grid, remaining_tiles - [tile]):
            # Mark the current cell as used
            grid[(x, y)] = True
            # Recursively try to place the remaining tiles on the rest of the grid
            if len(remaining_tiles) == n - len(tiles) and all(grid[x][y] == True for x in range(h) for y in range(w)):
                # All cells are covered, so return True
                return True
            # Backtrack: unmark the current cell and continue trying with the rest of the tiles
            grid[(x, y)] = False
            return False
    # Initial call to the recursive function, starting from the top left corner
    return place_tiles(0, 0, ((w + h - 1) // max(w, h) if w <= h else w), set(), [[False] * w for _ in range(h)], tiles)
