def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    if n < 3 or m > n * (n - 1):
        return None
    g = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        g[u].append((v, w, -w))
    for i in range(1, n + 1):
        g[i].sort(key=lambda x: x[1])
    visited = [False] * (n + 1)
    total_weight = 0
    heap = []
    heapq.heappush(heap, (0, 0, [1], total_weight))
    while heap:
        cur_weight, cur_node, path, total_weight = heapq.heappop(heap)
        if visited[cur_node]:
            continue
        visited[cur_node] = True
        if len(path) == n:
            return cur_weight
        for next_node, next_weight, _ in g[cur_node]:
            if not visited[next_node]:
                new_path = path + [next_node]
                heapq.heappush(heap, (cur_weight + next_weight, next_node, new_path, total_weight + next_weight))
    return None
