def shortest_palindrome_with_prefix(s):
    palindromes = ['']
    for i in range(len(s), 0, -1):
        ext_suffixes = [''.join((palindrome, palindrome[::-1])) for palindrome in palindromes]
        palindromes += [s[i:][::-1] + palindrome for palindrome in ext_suffixes if s[i:] + palindrome == palindrome[::-1]]
    if len(s) == 1:
        return s
    elif len(palindromes) == 0:
        return s + s[::-1]
    else:
        return min(palindromes, key=len)
