        return 0
    if view.total_length == 2:
        if legs_lengths[0] == legs_lengths[1]:
            return 0
        else:
            return 1

    maximum_length = max(legs_lengths)
    needed_stable_legs = ceil(len(legs_lengths) / 2.0)
    minimum_cost = float('inf')

    for i in range(len(legs_lengths)):
        if legs_lengths[i] == maximum_length:
            minimum_cost = min(minimum_cost, costs[i])
        if i < needed_stable_legs - 1:
            continue

    remaining_legs = len(legs_lengths) - needed_stable_legs
    minimum_cost += remaining_legs * maximum_length
    return minimum_cost
